#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int MOD1 = 998244353;
const int MOD2 = 1000000007;
const int BASE_VAL = 1000000;
vector<int> data[7];
int prefixSumData[7];
ll limitN;
ll countTotal, answerTotal;

void buildTree(int level, int prefix) {
    ++countTotal;
    data[level].push_back((countTotal - prefix + MOD1) % MOD1);
    prefixSumData[level] = (prefixSumData[level] + (countTotal - prefix + MOD1) % MOD1) % MOD2;
    if (level == 6) return;
    for (int digit = 0; digit < 10; ++digit)
        buildTree(level + 1, prefix * 10 + digit);
}

void traverseNumber(ll x) {
    if (x > limitN) return;
    if (x * BASE_VAL + BASE_VAL - 1 <= limitN && x * BASE_VAL * 10 > limitN) {
        ll currentCount = countTotal;
        for (int i = 0, factor = 1; i <= 6; ++i, factor *= 10) {
            int size = data[i].size();
            int diffVal = ((currentCount - x * factor) % MOD1 + MOD1) % MOD1;
            int pos = lower_bound(data[i].begin(), data[i].end(), MOD1 - diffVal) - data[i].begin();
            answerTotal = (answerTotal + 1ll * diffVal * size + prefixSumData[i]) % MOD2;
            answerTotal = (answerTotal - 1ll * MOD1 * (size - pos) % MOD2 + MOD2) % MOD2;
            countTotal += size;
        }
        return;
    }
    ++countTotal;
    answerTotal = (answerTotal + ((countTotal - x) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int digit = 0; digit <= 9; ++digit) traverseNumber(x * 10 + digit);
}

int main() {
    scanf("%lld", &limitN);
    buildTree(0, 0);
    for (int i = 0; i <= 6; ++i) sort(data[i].begin(), data[i].end());
    countTotal = 0;
    for (int i = 1; i <= 9; ++i) traverseNumber(i);
    printf("%lld\n", answerTotal);
    return 0;
}
